import { z } from 'zod';

/**
 * Schema for `src/2014/5e-SRD-Monsters-Normalized.json`, the generated, normalized monster file.
 *
 * The file is generated by `src/2014/normalize-monsters.ts` from `en/5e-SRD-Monsters.json` plus
 * `monster-engine-annotations.json` (see CONTRIBUTING.md), so it is never edited by hand. It is the
 * English monster shape with nested references (`{ index, name, url }`) collapsed to the plain
 * `index` string, `dc`/`condition` moved onto the last `damage` entry, and the annotations
 * merged in. Do not reshape the data here; this schema describes what the generator produces.
 */

// A collapsed reference: the `index` of a damage type, condition, ability score, proficiency, ...
const IndexSchema = z.string();

const DifficultyClassSchema = z.strictObject({
  dc_type: IndexSchema,
  dc_value: z.number().optional(),
  success_type: z.enum(['none', 'half', 'other']),
});

const ConditionDurationSchema = z.strictObject({
  length: z.number(),
  unit: z.string(),
  interrupt: z.string().optional(),
  interrupt_modifier: z.string().optional(),
});

const BaseConditionSchema = z.strictObject({
  condition_type: IndexSchema,
  duration: ConditionDurationSchema,
});

// A condition a failed save applies. `on_failed_repeat_save` makes it the first stage of a two-stage
// effect (petrification): the target repeats the same save at the end of its next turn, a success
// ends the condition and a failure replaces it with the condition named here. Added by the annotations.
const AppliedConditionSchema = BaseConditionSchema.extend({
  on_failed_repeat_save: BaseConditionSchema.optional(),
});

const GrappleSchema = z.strictObject({
  escape_dc_value: z.number(),
  additional_condition: BaseConditionSchema.optional(),
});

const MonsterSpeedSchema = z.strictObject({
  walk: z.number().optional(),
  burrow: z.number().optional(),
  climb: z.number().optional(),
  fly: z.number().optional(),
  swim: z.number().optional(),
  hover: z.boolean().optional(),
});

const SenseSchema = z.strictObject({
  passive_perception: z.number(),
  blindsight: z.number().optional(),
  blindsight_deafened: z.number().optional(),
  darkvision: z.number().optional(),
  tremorsense: z.number().optional(),
  truesight: z.number().optional(),
  blindsight_blind_beyond: z.boolean().optional(),
});

const MonsterProficiencySchema = z.strictObject({
  value: z.number(),
  proficiency: IndexSchema,
});

const MonsterArmorClassSchema = z.strictObject({
  type: z.string(),
  value: z.number(),
  armor: z.array(IndexSchema).optional(),
  condition: IndexSchema.optional(),
  spell: IndexSchema.optional(),
  desc: z.string().optional(),
});

const ActionUsageSchema = z.strictObject({
  type: z.string(),
  dice: z.string().optional(),
  min_value: z.number().optional(),
  times: z.number().optional(),
  rest_types: z.array(z.string()).optional(),
});

const MonsterDamageSchema = z.union([
  z.strictObject({
    damage_type: IndexSchema,
    damage_dice: z.string(),
    grapple: GrappleSchema.optional(),
    dc: DifficultyClassSchema.optional(),
    condition: AppliedConditionSchema.optional(),
  }),
  // Allowance: water-elemental's Engulf has a grapple-only entry, and the generator moves the action's
  // `dc` onto the last damage entry, so that one entry carries both `grapple` and `dc`.
  z.strictObject({ grapple: GrappleSchema, dc: DifficultyClassSchema.optional() }),
  // Effects with no damage dice: a save (`dc`) alone, or a save and the condition it applies.
  z.strictObject({ dc: DifficultyClassSchema.optional(), condition: AppliedConditionSchema }),
  z.strictObject({ dc: DifficultyClassSchema }),
]);

// A choice between damage options (one- or two-handed weapon damage, lightning or thunder).
const DamageChoiceSchema = z.strictObject({
  choose: z.number(),
  type: z.literal('damage'),
  from: z.strictObject({
    option_set_type: z.literal('options_array'),
    options: z.array(
      z.strictObject({
        option_type: z.literal('damage'),
        damage_type: IndexSchema,
        damage_dice: z.string(),
        notes: z.string().optional(),
      }),
    ),
  }),
});

// An action option that is itself a damage-and-save effect (a dragon's breath weapon).
const BreathOptionSchema = z.strictObject({
  option_type: z.literal('breath'),
  name: z.string(),
  dc: DifficultyClassSchema,
  damage: z.array(MonsterDamageSchema).optional(),
  condition: AppliedConditionSchema.optional(),
});

const OptionsChoiceSchema = z.strictObject({
  choose: z.number(),
  type: z.string().optional(),
  desc: z.string().optional(),
  from: z.strictObject({
    option_set_type: z.literal('options_array'),
    options: z.array(BreathOptionSchema),
  }),
});

const ActionOptionSchema = z.strictObject({
  option_type: z.literal('action'),
  action_name: z.string(),
  // Counts are numeric except hydra ("Number of Heads") and violet-fungus ("1d4"), which are not fixed counts.
  count: z.number(),
  type: z.string(),
  desc: z.string().optional(),
});

const ActionOptionsChoiceSchema = z.strictObject({
  choose: z.number(),
  type: z.string().optional(),
  desc: z.string().optional(),
  from: z.strictObject({
    option_set_type: z.literal('options_array'),
    options: z.array(
      z.union([
        ActionOptionSchema,
        z.strictObject({
          option_type: z.literal('multiple'),
          items: z.array(ActionOptionSchema),
          desc: z.string().optional(),
        }),
      ]),
    ),
  }),
});

const MonsterActionItemSchema = z.strictObject({
  action_name: z.string(),
  count: z.union([z.number(), z.string()]),
  type: z.string(),
});

const MonsterActionSituationSchema = z.strictObject({
  target: z.strictObject({
    condition: IndexSchema,
    max_size: z.enum(['Small', 'Medium']).optional(),
    conditionExcludes: z.boolean().optional(),
  }),
});

const MonsterAttackSchema = z.strictObject({
  name: z.string(),
  dc: DifficultyClassSchema.optional(),
  condition: AppliedConditionSchema.optional(),
  damage: z.array(MonsterDamageSchema).optional(),
});

const MonsterActionSchema = z.strictObject({
  name: z.string(),
  desc: z.string(),
  attack_type: z.enum(['Melee', 'Ranged']).optional(),
  preference: z
    .strictObject({
      type: z.enum(['always until first hit', 'always on first round', 'always unless target has condition']),
      target_condition: IndexSchema.optional(),
    })
    .optional(),
  situation: MonsterActionSituationSchema.optional(),
  // Distance in feet the action pulls each target straight toward the monster (the roper's Reel).
  pull_distance_ft: z.number().optional(),
  attack_bonus: z.number().optional(),
  weapon: z.string().optional(),
  weapon_kind: z.enum(['natural', 'manufactured', 'spell']).optional(),
  supply: z.strictObject({ item: z.string(), count: z.number() }).optional(),
  usage: ActionUsageSchema.optional(),
  multiattack_type: z.string().optional(),
  actions: z.array(MonsterActionItemSchema).optional(),
  action_options: ActionOptionsChoiceSchema.optional(),
  attacks: z.array(MonsterAttackSchema).optional(),
  options: OptionsChoiceSchema.optional(),
  damage: z.array(z.union([MonsterDamageSchema, DamageChoiceSchema])).optional(),
});

const LegendaryActionSchema = z.strictObject({
  name: z.string(),
  desc: z.string(),
  attack_bonus: z.number().optional(),
  damage: z.array(MonsterDamageSchema).optional(),
  dc: DifficultyClassSchema.optional(),
  condition: AppliedConditionSchema.optional(),
});

const ReactionSchema = z.strictObject({
  name: z.string(),
  desc: z.string(),
  dc: DifficultyClassSchema.optional(),
  condition: AppliedConditionSchema.optional(),
});

const SpecialAbilityUsageSchema = z.strictObject({
  type: z.string(),
  times: z.number().optional(),
  rest_types: z.array(z.string()).optional(),
});

const SpellcastingSpellSchema = z.strictObject({
  name: z.string(),
  level: z.number(),
  url: z.string(),
  usage: z.strictObject({ type: z.string(), times: z.number().optional() }).optional(),
  notes: z.string().optional(),
});

const SpellcastingSchema = z.strictObject({
  ability: IndexSchema,
  components_required: z.array(z.string()),
  spells: z.array(SpellcastingSpellSchema),
  level: z.number().optional(),
  dc: z.number().optional(),
  modifier: z.number().optional(),
  school: z.string().optional(),
  slots: z.record(z.string(), z.number()).optional(),
});

const SpecialAbilitySchema = z.strictObject({
  name: z.string(),
  desc: z.string(),
  attack_bonus: z.number().optional(),
  damage: z.array(MonsterDamageSchema).optional(),
  dc: DifficultyClassSchema.optional(),
  condition: AppliedConditionSchema.optional(),
  usage: SpecialAbilityUsageSchema.optional(),
  spellcasting: SpellcastingSchema.optional(),
  bonus_action: z
    .strictObject({
      action: z.string(),
      situation: z.strictObject({ target: z.strictObject({ condition: IndexSchema }) }),
    })
    .optional(),
  relentless_max_damage: z.number().optional(),
});

export const NormalizedMonsterSchema = z.strictObject({
  index: z.string(),
  name: z.string(),
  desc: z.string().optional(),
  size: z.string(),
  type: z.string(),
  subtype: z.string().optional(),
  alignment: z.string(),
  armor_class: z.array(MonsterArmorClassSchema),
  hit_points: z.number(),
  hit_dice: z.string(),
  hit_points_roll: z.string(),
  speed: MonsterSpeedSchema,
  strength: z.number(),
  dexterity: z.number(),
  constitution: z.number(),
  intelligence: z.number(),
  wisdom: z.number(),
  charisma: z.number(),
  proficiencies: z.array(MonsterProficiencySchema),
  damage_vulnerabilities: z.array(z.string()),
  damage_resistances: z.array(z.string()),
  damage_immunities: z.array(z.string()),
  condition_immunities: z.array(IndexSchema),
  senses: SenseSchema,
  languages: z.string(),
  challenge_rating: z.number(),
  proficiency_bonus: z.number().optional(),
  xp: z.number(),
  special_abilities: z.array(SpecialAbilitySchema).optional(),
  actions: z.array(MonsterActionSchema).optional(),
  legendary_actions: z.array(LegendaryActionSchema).optional(),
  reactions: z.array(ReactionSchema).optional(),
  environments: z.string().optional(),
  bonus_actions: z.array(z.string()).optional(),
  forms: z.array(IndexSchema).optional(),
  image: z.string().optional(),
  url: z.string(),
});
